function solarCalendar(dateStr,timeStr){
  var a=dateStr.split("-").map(Number),y=a[0],row=JIE_KST[y];
  if(!row)throw new RangeError("절입 시각표 지원 범위는 1900~2035년입니다.");
  var md=String(a[1]).padStart(2,"0")+String(a[2]).padStart(2,"0");
  var q=timeStr?timeStr.split(":").map(Number):[12,0,0];
  var stamp=md+String(q[0]).padStart(2,"0")+String(q[1]).padStart(2,"0")+String(q[2]||0).padStart(2,"0");
  var sm=11;for(var i=0;i<row.length&&stamp>=row[i];i++)sm=i===0?12:i;
  var boundaryDay=row.some(function(t){return t.slice(0,4)===md;});
  return {year:stamp<row[1]?y-1:y,month:sm,boundaryDay:boundaryDay,yearBoundaryDay:row[1].slice(0,4)===md,provisional:!timeStr&&boundaryDay};
}
function sajuMonth(dateStr,timeStr){return solarCalendar(dateStr,timeStr).month;}
function isJasi(timeStr){if(!timeStr)return false;var a=timeStr.split(":").map(Number);return a[0]*60+a[1]>=23*60+30;}
function fourPillars(dateStr,timeStr,jasi){
  var p=dateStr.split("-").map(Number),y=p[0],m=p[1],d=p[2];
  var yy=solarCalendar(dateStr,timeStr).year;
  var ys=((yy-4)%10+10)%10, yb=((yy-4)%12+12)%12;
  var sm=sajuMonth(dateStr,timeStr); var mb=(2+(sm-1))%12; var mStart=((ys%5)*2+2)%10; var ms=(mStart+(sm-1))%10;
  var night=isJasi(timeStr), shift=(night&&jasi!=="ya")?1:0;
  var dn=(jdn(y,m,d)+shift+49)%60, ds=dn%10, db=dn%12;
  var hds=(night&&jasi==="ya")?(ds+1)%10:ds;
  var hp=null;
  if(timeStr){var q=timeStr.split(":").map(Number);var t=(q[0]*60+q[1]+30)%1440;var hb=Math.floor(t/120);var hs=((hds%5)*2+hb)%10;hp={s:hs,b:hb};}
  return {y:{s:ys,b:yb}, m:{s:ms,b:mb}, d:{s:ds,b:db}, h:hp};
}
