function sinsin(dayS,s){var E="목화토금수";var i=E.indexOf(SEL[dayS]),k=E.indexOf(SEL[s]);var rel=(k-i+5)%5;var same=(dayS%2)===(s%2);var base=[0,2,4,6,8][rel];return SIN[same?base:base+1];}
/* ── 3) 신강/신약(간단판): 일간을 돕는 비겁·인성이 월지 3, 일지 2, 시지 1, 연지 1, 연간·월간·시간 각 1 → 합 4점 이상이면 신강 ── */
function strength(P){
  var score=0, parts=[];
  function helps(s){var r=sinsin(P.d.s,s);return r==="비견"||r==="겁재"||r==="편인"||r==="정인";}
  if(helps(BR_MAIN[P.m.b])){score+=3;parts.push("월지 "+BRS[P.m.b]+" +3");}
  if(helps(BR_MAIN[P.d.b])){score+=2;parts.push("일지 "+BRS[P.d.b]+" +2");}
  if(P.h&&helps(BR_MAIN[P.h.b])){score+=1;parts.push("시지 "+BRS[P.h.b]+" +1");}
  if(helps(BR_MAIN[P.y.b])){score+=1;parts.push("연지 "+BRS[P.y.b]+" +1");}
  if(helps(P.y.s)){score+=1;parts.push("연간 "+STEMS[P.y.s]+" +1");}
  if(helps(P.m.s)){score+=1;parts.push("월간 "+STEMS[P.m.s]+" +1");}
  if(P.h&&helps(P.h.s)){score+=1;parts.push("시간 "+STEMS[P.h.s]+" +1");}
  return {cls:score>=4?"신강":"신약", score:score, max:P.h?10:8, threshold:4, parts:parts};
}
/* ── 4) 2027 지지 미(未)와 일지·월지의 관계: 축 충 / 술 형·파 / 자 해 / 오 육합 / 묘·해 반합(함께 있으면 삼합) / 미 같음 / 그 외 없음. 우선순위 충>형파>해>합>같음>없음, 같은 급이면 둘 다 표기 ── */
var REL_OF={1:"충",10:"형파",0:"해",6:"합",3:"합",11:"합",7:"같음"};
var REL_KIND={1:"충(沖)",10:"형(刑)·파(破)",0:"해(害)",6:"육합(六合)",3:"반합(半合)",11:"삼합 계열(일부)",7:"같은 글자"};
